    border: 1px solid var(--accent-color-red);
    background: rgba(139, 0, 0, 0.1);
    border-radius: 4px;
}
.details-header {
    background: rgba(139, 0, 0, 0.3);
    padding: 8px 10px;
    font-weight: bold;
    font-size: 1.1em;
}
.details-content { padding: 10px; }
.details-content ul {
    list-style: none;
    padding: 0; margin: 0;
}
.details-content ul li {
    padding: 6px 0;
    border-bottom: 1px dashed rgba(139, 0, 0, 0.4);
    display: flex;
    justify-content: space-between;
}
.details-content ul li:last-child { border-bottom: none; }
.details-content ul li .key { opacity: 0.8; }
.details-content ul li .value { font-weight: bold; text-align: right; }

.mental-state {
    font-family: var(--font-en);
    font-style: italic;
    padding: 10px;
    margin-top: 8px;
    background: rgba(0,0,0,0.3);
    border-left: 3px solid var(--accent-color-amber);
    color: #ccc;
    white-space: pre-wrap;
    word-wrap: break-word;
}
.mental-state-title {
    font-family: var(--font-jp);
    font-style: normal;
    font-weight: bold;
    margin-bottom: 5px;
    color: var(--accent-color-amber);
}

.avatar-container {
    display: flex;
    align-items: center;
    gap: 15px;
    margin-bottom: 15px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--bezel-color);
