<body>
    <div class="hachishaku-raw-data">$1</div>

    <div class="hachishaku-hud">
        <div class="hud-toggle" id="hud-toggle">
            <span class="rec-light"></span>
            昔の日の誓い
            <span class="rec-light"></span>
        </div>

        <div class="hud-main-content" id="hud-main-content">
            <div class="hud-content-wrapper">
                <div class="hud-screen-overlay scanlines"></div>
                <div class="hud-screen-overlay noise"></div>
                <div class="hud-screen-overlay vignette"></div>

                <div class="hud-top-bar">
                    <span id="hud-date">DATE: --/--</span>
                    <span id="hud-location">LOC: UNKNOWN</span>
                    <span id="hud-time">TIME: --:--</span>
                </div>

                <div class="hud-content-area">
                    <div id="panel-player" class="hud-panel">加载用户数据中...</div>
                    <div id="panel-character" class="hud-panel">加载八尺様数据...</div>
                    <div id="panel-items" class="hud-panel">加载所持品数据...</div>
                    <div id="panel-tasks" class="hud-panel">加载任务数据...</div>
                </div>

                <div class="hud-nav">
                    <div class="nav-btn active" data-panel="panel-player">贵方</div>
                    <div class="nav-btn" data-panel="panel-character">彼女</div>
                    <div class="nav-btn" data-panel="panel-items">所持</div>
                    <div class="nav-btn" data-panel="panel-tasks">任务</div>
                </div>
            </div>
        </div>
    </div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const hud = document.querySelector('.hachishaku-hud');
    if (!hud) return;

    // --- Basic UI Interactivity ---
    const toggleButton = hud.querySelector('#hud-toggle');
    const mainContent = hud.querySelector('#hud-main-content');
    const navButtons = hud.querySelectorAll('.nav-btn');
    const panels = hud.querySelectorAll('.hud-panel');

    toggleButton.addEventListener('click', () => {
        const isHidden = mainContent.style.display === 'none' || mainContent.style.display === '';
        mainContent.style.display = isHidden ? 'block' : 'none';
        if(isHidden) {
            // Start data processing only when HUD is opened
            processData();
        }
    });

    navButtons.forEach(button => {
        button.addEventListener('click', () => {
            const targetId = button.getAttribute('data-panel');

            navButtons.forEach(btn => btn.classList.remove('active'));
            button.classList.add('active');

            panels.forEach(panel => {
                if (panel.id === targetId) {
                    panel.classList.add('active');
                    panel.classList.add('glitching');
                    setTimeout(() => panel.classList.remove('glitching'), 300);
                } else {
                    panel.classList.remove('active');
                }
            });
        });
    });

    // --- Data Processing ---
    const dataContainer = document.querySelector('.hachishaku-raw-data');

    // REVAMPED PARSING LOGIC
    function extractData(rawData, sectionName) {
        const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)\\[/${sectionName}\\]`, 'i');
        const match = rawData.match(regex);
        return match ? match[1].trim() : '';
    }

    function parseProperties(text) {
        const properties = {};
        if (!text) return properties;
        text.split('\n').forEach(line => {
            const index = line.indexOf(':');
            if (index > -1) {
                const key = line.substring(0, index).trim();
                const value = line.substring(index + 1).trim();
                if (key) { // Ensure key is not empty
                    properties[key] = value;
                }
            }
        });
        return properties;
    }

    function parseList(text) {
        if (!text) return [];
        return text.split('\n').map(line => line.replace(/^-/, '').trim()).filter(Boolean);
    }
    // END OF REVAMPED PARSING LOGIC

    function renderList(items) {
        if (!items || items.length === 0) return '<li><span class="value">无</span></li>';
        return items.map(item => `<li><span class="value">${item}</span></li>`).join('');
    }

    function renderKeyValueList(dataObject) {
        if (!dataObject) return '';
        return Object.entries(dataObject)
                     .map(([key, value]) => `<li><span class="key">${key}</span> <span class="value">${value}</span></li>`)
                     .join('');
    }

    function processData() {
        const rawData = dataContainer.textContent;
        if (!rawData) {
            panels.forEach(p => p.innerHTML = "<div class='details-group'><div class='details-header'>错误</div><div class='details-content'>未找到源数据。</div></div>");
            return;
        }

        const situationData = parseProperties(extractData(rawData, '状况'));
        const playerData = parseProperties(extractData(rawData, '用户状态'));
        const charData = parseProperties(extractData(rawData, '八尺状态'));
        const itemData = parseList(extractData(rawData, '所持品'));
        const taskData = parseProperties(extractData(rawData, '任务'));

        // --- Render Global Info ---
        document.getElementById('hud-date').innerHTML = `<i class="fa-solid fa-calendar-days"></i> ${situationData['日期'] || '--'}`;
        document.getElementById('hud-location').innerHTML = `<i class="fa-solid fa-location-dot"></i> ${situationData['地点'] || '未知'}`;
        document.getElementById('hud-time').innerHTML = `<i class="fa-solid fa-clock"></i> ${situationData['时刻'] || '--'}`;

        // --- Render Panels ---
        renderPlayerPanel(playerData);
        renderCharacterPanel(charData);
        renderItemsPanel(itemData);
        renderTasksPanel(taskData);

        // --- Set Initial Active Panel ---
        // Ensure the correct panel is active on first open
        const currentActive = hud.querySelector('.nav-btn.active');
        if(currentActive){
            const panelId = currentActive.getAttribute('data-panel');
            panels.forEach(p => p.classList.remove('active'));
            hud.querySelector(`#${panelId}`).classList.add('active');
        } else {
             hud.querySelector('.nav-btn[data-panel="panel-player"]').click();
        }

    }

    function renderPlayerPanel(data) {
        const panel = document.getElementById('panel-player');
        if(!panel) return;
        const coreInfo = {
            '生命力': data['生命力'] || '未知',
            '精神状态': data['精神状态'] || '未知',
            'san值': data['san值'] || '未知',
            '肉棒状态': data['肉棒状态'] || '未知'
        };
        panel.innerHTML = `
            <div class="avatar-container">
                <div class="user_avatar"></div>
                <h2 class="char-name">${data['姓名'] || '贵方'}</h2>
            </div>
            <div class="details-group">
                <div class="details-header">核心状态</div>
                <div class="details-content"><ul>${renderKeyValueList(coreInfo)}</ul></div>
            </div>
            <div class="mental-state">
                <div class="mental-state-title">内心独白</div>
                ${data['内心想法'] || '...'}
            </div>
        `;
    }

    function renderCharacterPanel(data) {
        const panel = document.getElementById('panel-character');
        if(!panel) return;
        const hachishakuAvatarUrl = 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEDUFho6nMC1M33FY_e9hfX-9AhBMw6eAACNBkAAtUQWVdCum4s36UJazYE.jpg';
        const coreInfo = {
            '好感度': data['好感度'] || '未知',
            '汲取状态': data['生命力汲取'] || '未知',
            '声音': data['啵啵声'] || '未知',
        };
        const bodyInfo = {
            '双乳': data['双乳'] || '未知',
            '腰臀': data['腰臀'] || '未知',
            '小穴': data['小穴'] || '未知',
            '双足': data['双足'] || '未知'
        };
        panel.innerHTML = `
            <div class="avatar-container">
                <div class="char_avatar" style="background-image: url('${hachishakuAvatarUrl}')"></div>
                <h2 class="char-name">${data['姓名'] || '八尺様'}</h2>
            </div>
            <div class="details-group">
                <div class="details-header">存在状态</div>
                <div class="details-content"><ul>${renderKeyValueList(coreInfo)}</ul></div>
            </div>
            <div class="details-group">
                <div class="details-header">肉体特征</div>
                <div class="details-content"><ul>${renderKeyValueList(bodyInfo)}</ul></div>
            </div>
            <div class="mental-state">
                <div class="mental-state-title">内心独白</div>
                ${data['内心想法'] || '...'}
            </div>
        `;
    }

    function renderItemsPanel(data) {
        const panel = document.getElementById('panel-items');
        if(!panel) return;
        panel.innerHTML = `
            <div class="details-group">
                <div class="details-header">所持品一览</div>
                <div class="details-content"><ul>${renderList(data)}</ul></div>
            </div>
        `;
    }

    function renderTasksPanel(data) {
        const panel = document.getElementById('panel-tasks');
        if(!panel) return;
        panel.innerHTML = `
            <div class="details-group">
                <div class="details-header">主要任务</div>
                <div class="details-content">
                    <ul>
                        <li><span class="value">${data['主要任务'] || '无'}</span></li>
                    </ul>
                </div>
            </div>
            <div class="details-group">
                <div class="details-header">当前目标</div>
                <div class="details-content">
                    <ul>
                        <li><span class="value">${data['当前目标'] || '无'}</span></li>
                    </ul>
                </div>
            </div>
        `;
    }

});
</script>
</body>
</html>
